export function symptomHistoryFor(english: string): SymptomHistoryPrompt[] {
  const normalized = english.trim().toLowerCase();
  const key = hpiByComplaint[normalized] || hpiAdditionalByComplaint[normalized]
    ? normalized
    : complaintAliases[normalized];
  return key ? hpiByComplaint[key] ?? hpiAdditionalByComplaint[key] ?? [] : [];
}
